types.definition:
export type ChartLabelFormatter = (
  value: string | number,
  datum: ChartDatum
) => React.ReactNode

export interface ChartReferenceLine {
  /** 参考线对应的数值。 */
  value: number
  /** 显示在参考线末端的文字。 */
  label?: React.ReactNode
  /** 覆盖参考线颜色。 */
  color?: string
  /** SVG 虚线模式。 @default "4 4" */
  strokeDasharray?: string
}

export interface ChartSeries {
  /** 数据字段名。 */
  key: string
  /** 图例和提示框中显示的名称。 */
  label?: string
  /** 覆盖当前序列的颜色。 */
  color?: string
  /** 折线序列的 SVG 虚线模式。 */
  strokeDasharray?: string
}

export type ChartValueFormatter = (
  value: number,
  series: ChartSeries,
  datum: ChartDatum
) => React.ReactNode
